class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frame = 1
        self.rolls_in_frame = 0
        self.first_roll = 0

    def roll(self, pins):
        if not 0 <= pins <= 10:
            raise Exception("Roll must score between 0 and 10 points")
        if self.is_game_over():
            raise Exception("Cannot roll after game is over")

        self.rolls.append(pins)

        if self.frame < 10:
            if self.rolls_in_frame == 0:
                if pins == 10:
                    self.advance_frame()
                else:
                    self.first_roll = pins
                    self.rolls_in_frame = 1
            else:
                if self.first_roll + pins > 10:
                    raise Exception(
                        "Two rolls in a frame cannot score more than 10 points"
                    )
                self.advance_frame()
        else:
            self.rolls_in_frame += 1
            if self.rolls_in_frame == 1:
                self.first_roll = pins
            elif self.rolls_in_frame == 2:
                if self.first_roll < 10 and self.first_roll + pins > 10:
                    raise Exception(
                        "Two rolls in a frame cannot score more than 10 points"
                    )
                if self.first_roll < 10:
                    self.advance_frame()
            else:
                if self.rolls[-2] < 10 and self.rolls[-2] + pins > 10:
                    raise Exception(
                        "Two bonus rolls cannot score more than 10 points"
                    )
                self.advance_frame()

    def advance_frame(self):
        self.frame += 1
        self.rolls_in_frame = 0
        self.first_roll = 0

    def is_game_over(self):
        return self.frame > 10

    def score(self):
        if not self.is_game_over():
            raise Exception("Game is not complete")

        total = 0
        i = 0
        for frame in range(1, 11):
            if frame < 10:
                if self.rolls[i] == 10:
                    total += 10 + self.rolls[i + 1] + self.rolls[i + 2]
                    i += 1
                elif self.rolls[i] + self.rolls[i + 1] == 10:
                    total += 10 + self.rolls[i + 2]
                    i += 2
                else:
                    total += self.rolls[i] + self.rolls[i + 1]
                    i += 2
            else:
                total += sum(self.rolls[i:])
        return total

